GB = 1024 ** 3

def kv_gb(layers, kv_heads, head_dim, seq, batch, dtype_bytes):
    # K 与 V 各一份, 故首项乘 2
    return 2 * layers * kv_heads * head_dim * seq * batch * dtype_bytes / GB


if __name__ == '__main__':
    print(round(kv_gb(32, 32, 128, 4096, 1, 2), 3))

import re

# 加数字边界 (?<![0-9]) ... (?![0-9])，避免把更长数字串的片段当成卡号
PAT = re.compile(r'(?<!\d)\d{16,19}(?!\d)')


def mask(s):
    return PAT.sub(lambda m: m.group()[:4] + ' **** **** ' + m.group()[-4:], s)


if __name__ == '__main__':
    print(mask('卡号 6222021234567890123 用于支付'))
    print(mask('订单号 202409190001 已发货'))
